const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

return [{
  json: {
    ...$input.first().json,
    SINCE_ISO: sevenDaysAgo.toISOString(),
    NOW_ISO: now.toISOString(),
    WINDOW_LABEL: `${sevenDaysAgo.toISOString().slice(0, 10)} to ${now.toISOString().slice(0, 10)}`
  }
}];

const config = $('Calculate Date Window').first().json;
const commits = $('Fetch Weekly Commits').all().map(i => i.json);
const issues = $('Fetch Closed Issues').all().map(i => i.json).filter(iss => !iss.pull_request);
const prs = $('Fetch Merged PRs').all().map(i => i.json).filter(pr => pr.merged_at && new Date(pr.merged_at) >= new Date(config.SINCE_ISO));

const commitsSummary = commits.slice(0, 40).map(c => `- ${c.commit?.message?.split('\n')[0]} (@${c.author?.login || 'unknown'})`).join('\n');
const issuesSummary = issues.slice(0, 25).map(iss => `- #${iss.number}: ${iss.title}`).join('\n');
const prsSummary = prs.slice(0, 25).map(pr => `- #${pr.number}: ${pr.title} (merged by @${pr.merged_by?.login || 'unknown'})`).join('\n');

const lang = (config.LANGUAGE || 'EN').toUpperCase();
const langInstruction = lang === 'FR'
  ? 'Rédige le résumé hebdomadaire en français, avec un ton professionnel et percutant.'
  : 'Write the weekly summary in English, with a professional and engaging developer tone.';

const prompt = `You are a Lead Staff Engineer and Technical Writer. Generate a comprehensive weekly developer digest for ${config.GITHUB_OWNER}/${config.GITHUB_REPO} covering the window ${config.WINDOW_LABEL}.

${langInstruction}

Activity Data:
--- COMMITS (${commits.length} total) ---
${commitsSummary || 'No commits recorded this week.'}

--- MERGED PULL REQUESTS (${prs.length} total) ---
${prsSummary || 'No pull requests merged this week.'}

--- RESOLVED ISSUES (${issues.length} total) ---
${issuesSummary || 'No issues closed this week.'}

Formatting Guidelines:
1. 🚀 Executive Narrative (3-4 sentences on the team\'s core engineering accomplishments).
2. ✨ Key Features & Enhancements (bulleted).
3. 🐛 Critical Bug Fixes & Hardening (bulleted).
4. 📊 Vital Metrics: Commits: ${commits.length} | Merged PRs: ${prs.length} | Closed Issues: ${issues.length}.
5. Keep formatting clean and markdown compatible.`;

return [{
  json: {
    ...config,
    prompt,
    totalCommits: commits.length,
    totalPRs: prs.length,
    totalIssues: issues.length
  }
}];

const prev = $('Aggregate Activity & Build Prompt').first().json;
const claudeResponse = $input.first().json;
const summaryText = claudeResponse.content?.[0]?.text || 'No summary generated.';
const channel = (prev.OUTPUT_CHANNEL || 'discord').toLowerCase();

let payload = {};
if (channel === 'discord') {
  payload = {
    content: `📢 **Weekly Dev Summary: ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO}** (${prev.WINDOW_LABEL})`,
    embeds: [{
      title: `🛠️ Engineering Digest — ${prev.WINDOW_LABEL}`,
      description: summaryText.slice(0, 4000),
      color: 5814783,
      fields: [
        { name: "Commits", value: `${prev.totalCommits}`, inline: true },
        { name: "Merged PRs", value: `${prev.totalPRs}`, inline: true },
        { name: "Closed Issues", value: `${prev.totalIssues}`, inline: true }
      ],
      footer: { text: "Generated by n8n + Claude Sonnet 4" }
    }]
  };
} else if (channel === 'slack') {
  payload = {
    text: `*Weekly Dev Summary: ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO}* (${prev.WINDOW_LABEL})\n\n${summaryText}`
  };
} else {
  payload = {
    subject: `Weekly Dev Summary: ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO} (${prev.WINDOW_LABEL})`,
    body: summaryText
  };
}

return [{
  json: {
    ...prev,
    payload,
    summaryText
  }
}];
